# ------------------------------------------------------------------ numbers
def pct(x, d=0):
    return f"{x * 100:.{d}f}"


def ac(model, split, var):
    e = R[model][split][var]
    return f"{e['auc']:.3f} / {pct(e['fake_caught'])}%"


def gen(model, src, var="clean"):
    g = R[model]["test_openfake"][var]["per_generator"][src]
    return g["auc"], g["caught"], g["n"]


def gc(model, src, var="clean"):
    a, c, _ = gen(model, src, var)
    return f"{a:.3f} / {pct(c)}%"


ci = lambda k: f"{A[k]['auc_ci'][0]:.3f}&ndash;{A[k]['auc_ci'][1]:.3f}"
cip = lambda k: f"{pct(A[k]['caught_ci'][0])}&ndash;{pct(A[k]['caught_ci'][1])}"
