va, ed, cal = R["v3"]["validation"]["clean"], R["v3"]["edited_heldout"], C["test_openfake"]
n_real, n_fake = v3c["n_real"], v3c["n_fake"]
_plan = HERE.parent / "data" / "features" / "v3" / "test_openfake_plan.json"
n_gen = (len(json.loads(_plan.read_text(encoding="utf-8"))) - 1) if _plan.exists() else 20
red = R["v3"]["test_reddit"]["clean"]

