_SMALL = {"and", "of", "to", "with", "the", "a", "an", "in", "on", "for", "vs.", "at"}


def capitalise_headings(html: str) -> str:
    import re
    html = re.sub(r"<h2>(.*?)</h2>", lambda m: f"<h2>{m.group(1).upper()}</h2>", html)

    def title(m):
        words = m.group(1).split(" ")
        out = [w if (w.lower() in _SMALL and k > 1) else (w[:1].upper() + w[1:]) for k, w in enumerate(words)]
        return f"<h3>{' '.join(out)}</h3>"
    return re.sub(r"<h3>(.*?)</h3>", title, html)


def head(named: bool) -> str:
    authors = ""
    if named:
        authors = ("<p class='au'>Pawan Singh Bhandari &nbsp;|&nbsp; Rahul H. Bramhankar &nbsp;|&nbsp; Bhoomi Kushwah</p>"
                   "<p class='af'>Department of Computer Engineering, JSPM's Bhivarabai Sawant Institute of Technology and Research, Wagholi, Pune, India<br>"
                   "Project guide: Dr. Gayatri Bhandari &nbsp;|&nbsp; Team: The Perceptrons</p>")
    return f"<h1>{TITLE}</h1>{authors}<p class='abs'><b>Abstract&mdash;</b>{ABSTRACT}</p><p class='abs'><b>Index Terms&mdash;</b>{KEYWORDS}.</p>"


def build(named: bool, out: Path) -> tuple[int, int]:
    html = capitalise_headings(body(named))
    # number the citations in order of first use (blocks and the full-width figures contain no citations)
    html, order = layout.number_citations(html, REFS)
    refs_html = '<div class="refs">' + "".join(f"<p>[{i}] {REFS[k]}</p>" for i, k in enumerate(order, start=1)) + "</div>"
    html = html.replace("@@REFS@@", refs_html)
    meta = {"title": TITLE, "author": "The Perceptrons" if named else "", "subject": "", "keywords": "", "creator": "", "producer": ""}
    footer = "The Perceptrons • Research Paper" if named else "Research Paper"
    n = layout.build_pdf(out, head(named), html.replace("@@REFS@@", refs_html), BLOCKS, CSS, HERE / "figures", FULL_WIDTH, footer, meta)
    return n, len(order)


if __name__ == "__main__":
    for named, name in ((True, "Full_Research_Paper_With_Authors.pdf"), (False, "Full_Research_Paper_Without_Authors.pdf")):
        pages, nrefs = build(named, HERE / name)
        print(name, pages, "pages,", nrefs, "references")
